#!/bin/bash
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
ICONSET="$ROOT/PocketKernel/Assets.xcassets/AppIcon.appiconset"
SVG="$RUNNER_TEMP/PocketKernel-AppIcon.svg"
PNG="$ICONSET/AppIcon-1024.png"
mkdir -p "$ICONSET"

cat <<'B64' | base64 --decode > "$SVG"

B64

if /usr/bin/sips -s format png "$SVG" --out "$PNG" >/dev/null 2>&1; then
  :
else
  PREVIEW_DIR="$RUNNER_TEMP/pocketkernel-icon-preview"
  rm -rf "$PREVIEW_DIR"
  mkdir -p "$PREVIEW_DIR"
  /usr/bin/qlmanage -t -s 1024 -o "$PREVIEW_DIR" "$SVG" >/dev/null 2>&1
  mv "$PREVIEW_DIR/$(basename "$SVG").png" "$PNG"
fi

/usr/bin/sips -z 1024 1024 "$PNG" >/dev/null
file "$PNG"
